const candidatesForAi =
  input.candidates.map((candidate) => {

    if (!candidate.fact_id) {
      throw new Error(
        '[Подготовить запрос Semantic Aggregator] У кандидата отсутствует fact_id'
      );
    }

    const evidence =
      Array.isArray(candidate.evidence)
        ? candidate.evidence.map((item) => ({
            quote: item.quote ?? null,
            type: item.type ?? null,
            role: item.role ?? null,

            page_from:
              item.page_from ?? null,

            page_to:
              item.page_to ?? null,

            sheet_name:
              item.sheet_name ?? null,

            semantic_block_id:
              item.semantic_block_id ?? null,
          }))
        : [];

    return {
      fact_id:
        candidate.fact_id,

      value_text:
        candidate.value_text ?? null,

      validator_verdict:
        candidate.validator_verdict ?? null,

      validator_confidence:
        candidate.validator_confidence ?? null,

      validator_reason_code:
        candidate.validator_reason_code ?? null,

      validator_reason_note:
        candidate.validator_reason_note ?? null,

      document: {
        document_id:
          candidate.document_id ?? null,

        document_index:
          candidate.document_index ?? null,

        file_name:
          candidate.file_name ?? null,

        file_extension:
          candidate.file_extension ?? null,
      },

      analysis_unit_id:
        candidate.analysis_unit_id ?? null,

      evidence,

      option_state:
        candidate.option_state ??
        null,

      applicability_proof:
        candidate.applicability_proof ??
        null,
    };
  });


