parameters.jsCode:
const input = $json;


// ============================================================
// 1. Проверяем вход
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[Metadata Resolver] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Metadata Resolver] Нет field_key'
  );
}


// ============================================================
// 2. Получаем tender_meta один раз из Aggregator
// ============================================================

let tenderMeta =
  $('Загрузить факты закупки')
    .first()
    .json
    .tender_meta ?? null;


// На случай если Postgres когда-нибудь вернёт JSON строкой.
if (typeof tenderMeta === 'string') {

  try {
    tenderMeta =
      JSON.parse(tenderMeta);
  } catch {
    throw new Error(
      '[Metadata Resolver] tender_meta является строкой, но невалидным JSON'
    );
  }
}


if (
  !tenderMeta ||
  typeof tenderMeta !== 'object'
) {
  throw new Error(
    '[Metadata Resolver] tender_meta отсутствует'
  );
}


// ============================================================
// 3. Результат по умолчанию
//
// Очень важно:
// отсутствие правила здесь НЕ означает not_found.
// Оно означает:
// "Metadata Resolver не смог закрыть поле,
// передай его дальше в Targeted Recheck".
// ============================================================

let metadataResolved =
  false;

let finalValueText =
  null;

let metadataEvidence =
  [];


// ============================================================
// 4. PLATFORM
//
// Это строгое детерминированное соответствие:
//
// field_key = platform
// ↓
// tender_meta.platform
//
// Никакой AI здесь не нужен.
// ============================================================

if (input.field_key === 'platform') {

  const platform =
    tenderMeta.platform;


  if (
    platform &&
    typeof platform === 'object'
  ) {

    const name =
      typeof platform.name === 'string'
        ? platform.name.trim()
        : '';

    const url =
      typeof platform.url === 'string'
        ? platform.url.trim()
        : '';


    // Для финального текстового поля приоритетно
    // используем название площадки.
    //
    // URL сохраняем в provenance отдельно.
    if (name || url) {

      metadataResolved =
        true;

      finalValueText =
        name || url;

      metadataEvidence = [
        {
          source_type:
            'tender_metadata',

          metadata_key:
            'platform',

          value:
            platform,
        },
      ];
    }
  }
}


// ============================================================
// APPLICATION DEADLINE
// ============================================================

if (
  input.field_key === 'application_deadline' &&
  !metadataResolved
) {

  const submissionCloseAt =
    tenderMeta.submission_close_at;

  if (
    typeof submissionCloseAt === 'string' &&
    submissionCloseAt.trim()
  ) {

    metadataResolved =
      true;

    finalValueText =
      submissionCloseAt.trim();

    metadataEvidence = [
      {
        source_type:
          'tender_metadata',

        metadata_key:
          'submission_close_at',

        value:
          submissionCloseAt,
      },
    ];
  }
}

// ============================================================
// PROCUREMENT SUBJECT
// ============================================================

if (
  input.field_key === 'procurement_subject' &&
  !metadataResolved
) {

  const title =
    tenderMeta.title;

  if (
    typeof title === 'string' &&
    title.trim()
  ) {

    metadataResolved =
      true;

    finalValueText =
      title.trim();

    metadataEvidence = [
      {
        source_type:
          'tender_metadata',

        metadata_key:
          'title',

        value:
          title,
      },
    ];
  }
}


// ============================================================
// CUSTOMER
// ============================================================

if (
  input.field_key === 'customer' &&
  !metadataResolved
) {

  const primaryCustomer =
    tenderMeta.primary_customer;

  if (
    primaryCustomer &&
    typeof primaryCustomer === 'object' &&
    typeof primaryCustomer.name === 'string' &&
    primaryCustomer.name.trim()
  ) {

    metadataResolved =
      true;

    finalValueText =
      primaryCustomer.name.trim();

    metadataEvidence = [
      {
        source_type:
          'tender_metadata',

        metadata_key:
          'primary_customer',

        value:
          primaryCustomer,
      },
    ];
  }
}

// ============================================================
// 5. Возвращаем унифицированный результат
// ============================================================

return {
  json: {

    // Исходная идентификация поля
    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
      input.field_catalog_version,

    field_index:
      input.field_index,

    field_key:
      input.field_key,


    // Было ли поле закрыто Metadata Resolver
    metadata_resolved:
      metadataResolved,


    // Если resolved — это уже готовый результат поля.
    // Если false — поле уйдёт дальше в Targeted Recheck.
    aggregation_status:
      metadataResolved
        ? 'resolved'
        : null,

    final_value_text:
      finalValueText,

    confidence:
      metadataResolved
        ? 1
        : null,


    // Откуда взялось значение
    resolution_method:
      metadataResolved
        ? 'deterministic_metadata'
        : null,

    evidence:
      metadataEvidence,


    // Сохраняем исходный grouped field,
    // чтобы следующая ветка ничего не потеряла.
    original_field:
      input,
  },
};

const input = $json;


// ============================================================
// 1. Проверяем вход
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[Сформировать FINAL после Round 1] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Сформировать FINAL после Round 1] Нет field_key'
  );
}

if (input.aggregation_validated !== true) {
  throw new Error(
    '[Сформировать FINAL после Round 1] aggregation_validated !== true'
  );
}

if (input.aggregation_status !== 'resolved') {
  throw new Error(
    `[Сформировать FINAL после Round 1] Ожидался resolved, получено: ${input.aggregation_status}`
  );
}

if (input.needs_recheck !== false) {
  throw new Error(
    '[Сформировать FINAL после Round 1] needs_recheck должен быть false'
  );
}

if (
  typeof input.final_value_text !== 'string' ||
  !input.final_value_text.trim()
) {
  throw new Error(
    '[Сформировать FINAL после Round 1] Нет final_value_text'
  );
}

if (
  typeof input.confidence !== 'number' ||
  input.confidence < 0 ||
  input.confidence > 1
) {
  throw new Error(
    '[Сформировать FINAL после Round 1] Некорректный confidence'
  );
}


// ============================================================
// 2. Собираем evidence использованных кандидатов
// ============================================================

const candidates =
  Array.isArray(input.aggregation_input?.candidates)
    ? input.aggregation_input.candidates
    : [];

const decisions =
  Array.isArray(input.candidate_decisions)
    ? input.candidate_decisions
    : [];

const candidateByFactId = new Map(
  candidates
    .filter(candidate => candidate.fact_id)
    .map(candidate => [
      candidate.fact_id,
      candidate,
    ])
);


// В resolved-результат включаем evidence кандидатов,
// которые реально поддерживают итог.
//
// conflict и not_applicable в основной evidence не включаем.
const acceptedRoles = new Set([
  'primary',
  'duplicate',
  'supporting',
  'complement',
]);

const evidence = [];

for (const decision of decisions) {

  if (!acceptedRoles.has(decision.role)) {
    continue;
  }

  const candidate =
    candidateByFactId.get(decision.fact_id);

  if (!candidate) {
    throw new Error(
      `[Сформировать FINAL после Round 1] Не найден candidate для fact_id=${decision.fact_id}`
    );
  }

  const candidateEvidence =
    Array.isArray(candidate.evidence)
