    if (primaryCount !== 1 || conflictSet.size > 0) throw new Error('resolved roles mismatch');
  }
  if (result.status === 'requires_recheck') {
    if (result.needs_recheck !== true) throw new Error('recheck flag mismatch');
    if (!allowedRecheckCodes.has(result.recheck_reason_code)) throw new Error('invalid recheck code');
    if (typeof result.recheck_note !== 'string' || !result.recheck_note.trim()) throw new Error('missing recheck note');
    if (primaryCount > 1) throw new Error('too many primary decisions');
  }

  retryEligible = true;
} catch {
  retryEligible = false;
  missingFactIds = [];
}

return {
  json: {
    ...aiResponse,
    semantic_aggregator_retry_required: retryEligible,
    semantic_aggregator_retry_attempt: retryEligible ? 1 : 0,
    missing_fact_ids: missingFactIds,
    original_ai_response: aiResponse,
  },
};

const input = $json;
const source = $('Подготовить запрос Semantic Aggregator').item.json;

if (input.semantic_aggregator_retry_required !== true || input.semantic_aggregator_retry_attempt !== 1) {
  throw new Error('[Подготовить retry Semantic Aggregator] Retry contract не подтверждён');
}
if (!Array.isArray(input.missing_fact_ids) || input.missing_fact_ids.length !== 1) {
  throw new Error('[Подготовить retry Semantic Aggregator] Ожидался ровно один missing fact_id');
}

const missingFactId = input.missing_fact_ids[0];
const allowedFactIds = Array.isArray(source.allowed_fact_ids) ? source.allowed_fact_ids : [];
if (!allowedFactIds.includes(missingFactId)) {
  throw new Error('[Подготовить retry Semantic Aggregator] missing fact_id отсутствует в allow-list');
}

const repairInstruction = [
  'Предыдущий ответ нарушил технический контракт: отсутствует решение ровно для fact_id=' + missingFactId + '.',
  'Верни полный новый JSON для всех candidate facts, используя каждый allowed fact_id ровно один раз.',
  'Allowed fact_id: ' + JSON.stringify(allowedFactIds) + '.',
  'Не назначай роль отсутствующему candidate автоматически: заново оцени каждый candidate по исходным правилам.',
  'Не добавляй неизвестные fact_id и не меняй field_key.',
].join('\n');

return {
  json: {
    ...source,
    system_prompt: source.system_prompt,
    user_prompt: source.user_prompt + '\n\nТЕХНИЧЕСКОЕ ИСПРАВЛЕНИЕ ОТВЕТА:\n' + repairInstruction,
    repair_instruction: repairInstruction,
    semantic_aggregator_retry_attempt: 2,
    missing_fact_ids: [missingFactId],
    allowed_fact_ids: allowedFactIds,
    aggregation_input: source.aggregation_input,
  },
};

