const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `[Сгруппировать факты по полям] Ожидался 1 item, получено: ${items.length}`
  );
}

const input = items[0].json;


// ============================================================
// 1. Каталог tender_fields_v1
// ============================================================

const FIELD_KEYS = [
  'procurement_subject',
  'nm_price_with_vat',
  'platform',
  'procedure_type',
  'application_deadline',
  'application_review_date',
  'results_date',
  'customer',
  'customer_contacts',
  'participation_cost',
  'participation_guarantee',
  'evaluation_criteria',
  'delivery_term',
  'payment_terms',
  'special_account_or_treasury',
  'bank_support',
  'government_contract',
  'rebidding',
  'national_regime',
  'advance_contract_guarantee',
  'warranty_obligations_guarantee',
  'licenses_certificates',
  'required_official_certificates',
  'similar_supply_experience',
  'analog_allowed',
  'analog_definition',
  'application_documents',
];

const allowedFieldKeys =
  new Set(FIELD_KEYS);


const facts =
  Array.isArray(input.facts)
    ? input.facts
    : [];

const documents =
  Array.isArray(input.documents)
    ? input.documents
    : [];


// ============================================================
// 2. Создаём все 27 групп заранее
// ============================================================

const groups =
  new Map(
    FIELD_KEYS.map(
      fieldKey => [
        fieldKey,
        [],
      ]
    )
  );


// ============================================================
// 3. Раскладываем candidate facts по field_key
// ============================================================

for (const fact of facts) {
  const fieldKey =
    fact?.field_key;

  if (
    typeof fieldKey !== 'string' ||
    !allowedFieldKeys.has(fieldKey)
  ) {
    throw new Error(
      `[Сгруппировать факты по полям] Неизвестный field_key: ${fieldKey}`
    );
  }

  groups
    .get(fieldKey)
    .push(fact);
}


// ============================================================
// 4. Один output item = одно поле каталога
// ============================================================

return FIELD_KEYS.map(
  (
    fieldKey,
    fieldIndex
  ) => {
    const candidates =
      groups.get(fieldKey);

    const confirmedCount =
      candidates.filter(
        fact =>
          fact.validator_verdict ===
          'confirmed'
      ).length;

    const requiresReviewCount =
      candidates.filter(
        fact =>
          fact.validator_verdict ===
          'requires_review'
      ).length;


    const documentIds =
      [
        ...new Set(
          candidates
            .map(
              fact =>
                fact.document_id
            )
            .filter(Boolean)
        ),
      ];


    const sourceDocuments =
      documents
        .filter(
          document =>
            documentIds.includes(
              document.document_id
            )
        )
        .map(
          document => ({
            document_id:
              document.document_id,

            document_index:
              document.document_index,

            file_name:
              document.file_name,

            file_extension:
              document.file_extension,
          })
        );


    return {
      json: {
        analysis_run_id:
          input.analysis_run_id,

        field_catalog_version:
          'tender_fields_v1',

        field_index:
          fieldIndex + 1,

        field_key:
          fieldKey,

        has_candidates:
          candidates.length > 0,

        candidates_count:
          candidates.length,

        confirmed_count:
          confirmedCount,

        requires_review_count:
          requiresReviewCount,

        source_documents_count:
          sourceDocuments.length,

        source_documents:
          sourceDocuments,

        candidates,
      },
    };
  }
);

const input = $json;

if (!input.analysis_run_id) {
  throw new Error(
    '[Подготовить запрос Semantic Aggregator] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Подготовить запрос Semantic Aggregator] Нет field_key'
  );
}

if (!Array.isArray(input.candidates)) {
  throw new Error(
    '[Подготовить запрос Semantic Aggregator] candidates должен быть массивом'
  );
}


// ============================================================
// Правила смысловой агрегации по field_key.
// Сейчас отлаживаем:
// - procurement_subject
// - delivery_term
// ============================================================

const FIELD_RULES = {

  // ============================================================
  // 1. Предмет закупки
  // ============================================================

  procurement_subject: {
    title: 'Предмет закупки',

    definition:
      'Конкретный товар, работа или услуга, которые закупаются.',

    rules: [
      'Предпочитай конкретное и полное описание предмета закупки более общей формулировке.',
      'Фразы вроде "поставка товара", "оказание услуг" или "выполнение работ" являются слишком общими, если есть более точное описание.',
      'Если несколько кандидатов описывают один и тот же предмет с разной детализацией, это не конфликт.',
      'Более подробный кандидат может быть primary, а более общий — supporting или duplicate.',
      'Не добавляй цену, сроки, заказчика и другие сведения, не относящиеся к предмету закупки.',
      'Candidate применим только тогда, когда evidence прямо устанавливает, что описанный товар, работа или услуга являются объектом именно текущей закупки либо договора, заключаемого по текущей закупке.',
      'Конкретность формулировки сама по себе не доказывает применимость или относимость candidate к текущей закупке.',
      'Внутренние процессы организации, включая организационные, производственные, контрольные, эксплуатационные или административные процессы, не являются предметом закупки, если evidence прямо не устанавливает обратное.',
      'Вспомогательные обязательства, а также обязательства, предметы и процессы другого договора, отдельного соглашения, NDA, приложения, шаблона или вспомогательного отношения должны быть not_applicable, если они не являются объектом текущей закупки.',
      'Если связь candidate с current procurement scope неоднозначна или требует предположения, считай это ambiguous_scope и установи status=requires_recheck, needs_recheck=true и recheck_reason_code=ambiguous_scope.',
      'Candidate с validator_verdict="requires_review" и ambiguous_scope нельзя повышать до resolved без дополнительного подтверждения scope прямым evidence.',
    ],
  },


  // ============================================================
  // 2. НМЦ / НМЦК + НДС
  // ============================================================

  nm_price_with_vat: {
    title: 'НМЦ / НМЦК с информацией об НДС',

    definition:
      'Начальная максимальная цена закупки или контракта и сведения об НДС, только если соответствующий смысл подтверждён источниками.',

    rules: [
      'Не считай любую цену товара, сумму спецификации или стоимость позиции автоматически НМЦ или НМЦК.',
      'Для automatic resolved должно быть достаточно оснований связать найденное значение именно с начальной максимальной ценой закупки или контракта.',
      'Если кандидат содержит сумму и указание "в т.ч. НДС", но evidence не доказывает, что эта сумма является именно НМЦ или НМЦК, требуется recheck.',
