const aiResponse = $json;

const source =
  $('Подготовить запрос Semantic Aggregator').item.json;


// ============================================================
// 1. Проверяем технический ответ API
// ============================================================

const choice =
  aiResponse?.choices?.[0];

if (!choice) {
  throw new Error(
    '[Semantic Aggregator Validator] В ответе отсутствует choices[0]'
  );
}

if (choice.finish_reason !== 'stop') {
  throw new Error(
    `[Semantic Aggregator Validator] Некорректный finish_reason: ${choice.finish_reason}`
  );
}

const content =
  choice?.message?.content;

if (
  typeof content !== 'string' ||
  !content.trim()
) {
  throw new Error(
    '[Semantic Aggregator Validator] message.content пуст'
  );
}


// ============================================================
// 2. Парсим JSON модели
// ============================================================

let result;

try {
  result = JSON.parse(content);
} catch (error) {
  throw new Error(
    `[Semantic Aggregator Validator] Модель вернула невалидный JSON: ${error.message}`
  );
}


// ============================================================
// 3. Разрешённые значения
// ============================================================

const ALLOWED_STATUSES =
  new Set([
    'resolved',
    'requires_recheck',
  ]);

const ALLOWED_ROLES =
  new Set([
    'primary',
    'duplicate',
    'supporting',
    'complement',
    'conflict',
    'not_applicable',
  ]);

const ALLOWED_RECHECK_CODES =
  new Set([
    'conflicting_candidates',
    'insufficient_evidence',
    'ambiguous_scope',
    'no_reliable_candidate',
    'other',
  ]);


// ============================================================
// 4. Проверяем field_key
// ============================================================

if (result.field_key !== source.field_key) {
  throw new Error(
    `[Semantic Aggregator Validator] field_key изменён: ожидался ${source.field_key}, получен ${result.field_key}`
  );
}


// ============================================================
// 5. Проверяем status
// ============================================================

if (!ALLOWED_STATUSES.has(result.status)) {
  throw new Error(
    `[Semantic Aggregator Validator] Недопустимый status: ${result.status}`
  );
}


// ============================================================
// 6. Проверяем confidence
// ============================================================

if (
  typeof result.confidence !== 'number' ||
  !Number.isFinite(result.confidence) ||
  result.confidence < 0 ||
  result.confidence > 1
) {
  throw new Error(
    `[Semantic Aggregator Validator] Некорректный confidence: ${result.confidence}`
  );
}


// ============================================================
// 7. Проверяем candidate_decisions
// ============================================================

if (!Array.isArray(result.candidate_decisions)) {
  throw new Error(
    '[Semantic Aggregator Validator] candidate_decisions должен быть массивом'
  );
}

const allowedFactIds =
  Array.isArray(source.allowed_fact_ids)
    ? source.allowed_fact_ids
    : [];

const allowedFactIdSet =
  new Set(allowedFactIds);

if (
  result.candidate_decisions.length !==
  allowedFactIds.length
) {
  throw new Error(
    `[Semantic Aggregator Validator] Ожидалось ${allowedFactIds.length} candidate_decisions, получено ${result.candidate_decisions.length}`
  );
}

const usedFactIds =
  new Set();

const decisionByFactId =
  new Map();

for (const decision of result.candidate_decisions) {

  if (
    typeof decision?.fact_id !== 'string' ||
    !decision.fact_id
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] candidate_decision без fact_id'
    );
  }

  if (!allowedFactIdSet.has(decision.fact_id)) {
    throw new Error(
      `[Semantic Aggregator Validator] Модель придумала неизвестный fact_id: ${decision.fact_id}`
    );
  }

  if (usedFactIds.has(decision.fact_id)) {
    throw new Error(
      `[Semantic Aggregator Validator] fact_id повторяется: ${decision.fact_id}`
    );
  }

  usedFactIds.add(
    decision.fact_id
  );

  if (!ALLOWED_ROLES.has(decision.role)) {
    throw new Error(
      `[Semantic Aggregator Validator] Недопустимая role=${decision.role} для fact_id=${decision.fact_id}`
    );
  }

  if (
    typeof decision.reason !== 'string' ||
    !decision.reason.trim()
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Нет reason для fact_id=${decision.fact_id}`
    );
  }

  decisionByFactId.set(
    decision.fact_id,
    decision
  );
}


// ============================================================
// 8. Убеждаемся, что ни один входной fact не потерян
// ============================================================

for (const factId of allowedFactIds) {
  if (!usedFactIds.has(factId)) {
    throw new Error(
      `[Semantic Aggregator Validator] В ответе потерян fact_id=${factId}`
    );
  }
}


// ============================================================
// 9. Проверяем supporting_fact_ids
// ============================================================

if (!Array.isArray(result.supporting_fact_ids)) {
  throw new Error(
    '[Semantic Aggregator Validator] supporting_fact_ids должен быть массивом'
  );
}

const supportingSet =
  new Set();

for (const factId of result.supporting_fact_ids) {

  if (!allowedFactIdSet.has(factId)) {
    throw new Error(
      `[Semantic Aggregator Validator] Неизвестный supporting fact_id=${factId}`
    );
  }

  if (supportingSet.has(factId)) {
    throw new Error(
      `[Semantic Aggregator Validator] Дубликат supporting fact_id=${factId}`
    );
  }

  supportingSet.add(factId);

  const role =
    decisionByFactId.get(factId)?.role;

  if (
    role === 'conflict' ||
    role === 'not_applicable'
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] fact_id=${factId} имеет role=${role}, но указан как supporting`
    );
  }
}


// ============================================================
// 10. Проверяем conflict_fact_ids
// ============================================================

if (!Array.isArray(result.conflict_fact_ids)) {
  throw new Error(
    '[Semantic Aggregator Validator] conflict_fact_ids должен быть массивом'
  );
}

const conflictSet =
  new Set();

for (const factId of result.conflict_fact_ids) {

  if (!allowedFactIdSet.has(factId)) {
    throw new Error(
      `[Semantic Aggregator Validator] Неизвестный conflict fact_id=${factId}`
    );
  }

  if (conflictSet.has(factId)) {
    throw new Error(
      `[Semantic Aggregator Validator] Дубликат conflict fact_id=${factId}`
    );
  }

  conflictSet.add(factId);
}


// Все role=conflict обязаны находиться в conflict_fact_ids
for (const decision of result.candidate_decisions) {

  const listedAsConflict =
    conflictSet.has(decision.fact_id);

  if (
    decision.role === 'conflict' &&
    !listedAsConflict
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] fact_id=${decision.fact_id} имеет role=conflict, но отсутствует в conflict_fact_ids`
    );
  }

  if (
    decision.role !== 'conflict' &&
    listedAsConflict
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] fact_id=${decision.fact_id} указан в conflict_fact_ids, но role=${decision.role}`
    );
  }
}


function normalizeApplicabilityText(value) {
  return String(value ?? '').normalize('NFKC').replace(/\s+/g, ' ').trim();
}

function evidenceRefMatchesCandidate(ref, candidate, { allowLabelContainment = false } = {}) {
  if (!ref || typeof ref.semantic_block_id !== 'string' || ref.semantic_block_id.length === 0) return false;
  const candidateEvidence = Array.isArray(candidate?.evidence) ? candidate.evidence : [];
  return candidateEvidence.some((evidence) => {
    if (evidence?.semantic_block_id !== ref.semantic_block_id) return false;
    const candidateQuote = normalizeApplicabilityText(evidence?.quote);
    const refText = normalizeApplicabilityText(ref?.quote ?? ref?.exact_label);
    if (!candidateQuote || !refText) return false;
    if (allowLabelContainment) {
      return candidateQuote.includes(refText);
    }
    return candidateQuote === refText;
  });
}

function assessNationalRegimeApplicability(source, result) {
  if (source?.field_catalog_version !== 'tender_fields_v1' || source?.field_key !== 'national_regime' || result?.field_key !== 'national_regime') {
    return { required: false, proven: false, proof_kind: null, primary_fact_id: null };
  }
  const primaryDecision = result.candidate_decisions.find((decision) => decision?.role === 'primary') ?? null;
  const candidates = Array.isArray(source?.aggregation_input?.candidates) ? source.aggregation_input.candidates : [];
  const primaryCandidate = primaryDecision
    ? candidates.find((candidate) => candidate?.fact_id === primaryDecision.fact_id) ?? null
    : null;
  if (!primaryCandidate || primaryCandidate.validator_verdict !== 'confirmed') {
    return { required: true, proven: false, proof_kind: null, primary_fact_id: primaryDecision?.fact_id ?? null };
  }

  const normalizedPrimaryValue = normalizeApplicabilityText(primaryCandidate.value_text);
  const finalValueBoundToPrimary =
    normalizedPrimaryValue.length > 0 &&
    normalizeApplicabilityText(result.final_value_text) === normalizedPrimaryValue;

  const optionState = primaryCandidate.option_state;
  const optionEvidence = Array.isArray(optionState?.evidence) ? optionState.evidence : [];
  const optionWarnings = Array.isArray(optionState?.warnings) ? optionState.warnings : [];
  const selectedOptionProven =
    optionState?.contract_version === 'docx_option_state_fact_audit_v1' &&
    optionState?.applicability === 'applicable' &&
    optionWarnings.length === 0 &&
    finalValueBoundToPrimary &&
    optionEvidence.length > 0 &&
    optionEvidence.every((entry) =>
      entry?.state === 'selected' &&
      evidenceRefMatchesCandidate(entry, primaryCandidate, { allowLabelContainment: true })
    );
  if (selectedOptionProven) {
    return { required: true, proven: true, proof_kind: 'selected_option_state', primary_fact_id: primaryCandidate.fact_id };
  }

  const explicitProof = primaryCandidate.applicability_proof;
  const explicitEvidenceRefs = Array.isArray(explicitProof?.evidence_refs) ? explicitProof.evidence_refs : [];
  const explicitCurrentProcurementProven =
    explicitProof?.contract_version === 'current_procurement_applicability_v1' &&
    explicitProof?.applicability === 'applicable' &&
    explicitProof?.source === 'deterministic_source_contract' &&
    finalValueBoundToPrimary &&
    explicitEvidenceRefs.length > 0 &&
    explicitEvidenceRefs.every((entry) => evidenceRefMatchesCandidate(entry, primaryCandidate));
  if (explicitCurrentProcurementProven) {
    return { required: true, proven: true, proof_kind: 'explicit_current_procurement', primary_fact_id: primaryCandidate.fact_id };
  }

  return { required: true, proven: false, proof_kind: null, primary_fact_id: primaryCandidate.fact_id };
}


// ============================================================
// 11. Проверяем согласованность resolved / requires_recheck
// ============================================================

const primaryCount =
  result.candidate_decisions.filter(
    decision =>
      decision.role === 'primary'
  ).length;


const ROUND1_CONTAINMENT_BY_FIELD = {
  national_regime: {
    policy: 'national_regime_round1_applicability_v1',
    reason: 'Применимость национального режима к текущей закупке не доказана структурированным evidence; требуется Targeted Recheck.',
  },
  application_documents: {
    policy: 'application_documents_round1_requires_recheck_v1',
    reason: 'Полнота составного перечня документов заявки не доказана детерминированно; требуется Targeted Recheck.',
  },
  participation_guarantee: {
    policy: 'participation_guarantee_round1_requires_recheck_v1',
    reason: 'Фактическая применимость обеспечения заявки и его размер не доказаны детерминированно; требуется Targeted Recheck.',
  },
  required_official_certificates: {
    policy: 'required_official_certificates_round1_requires_recheck_v1',
    reason: 'Полнота перечня обязательных официальных документов об участнике и его статусе не доказана детерминированно; требуется Targeted Recheck.',
  },
};

const containmentRule =
  source.field_catalog_version === 'tender_fields_v1' &&
  source.field_key === result.field_key
    ? ROUND1_CONTAINMENT_BY_FIELD[source.field_key] ?? null
    : null;

const applicabilityAssessment =
  assessNationalRegimeApplicability(source, result);

const resolvedContainmentEligible =
  result.status === 'resolved' &&
  containmentRule !== null &&
  (
    source.field_key !== 'national_regime' ||
    !applicabilityAssessment.proven
  );

const applicationDocumentsResolvedContainmentEligible =
  resolvedContainmentEligible &&
  source.field_key === 'application_documents';

const resolvedPrimaryCardinalityInvalid =
  result.status === 'resolved' &&
  primaryCount !== 1;


if (result.status === 'resolved') {

  if (
    typeof result.final_value_text !== 'string' ||
    !result.final_value_text.trim()
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Для resolved требуется final_value_text'
    );
  }

  if (result.needs_recheck !== false) {
    throw new Error(
      '[Semantic Aggregator Validator] Для resolved needs_recheck должен быть false'
    );
  }

  if (result.recheck_reason_code !== null) {
    throw new Error(
      '[Semantic Aggregator Validator] Для resolved recheck_reason_code должен быть null'
    );
  }

  if (
    primaryCount !== 1 &&
    !applicationDocumentsResolvedContainmentEligible
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Для resolved ожидается ровно один primary, получено ${primaryCount}`
    );
  }

  if (conflictSet.size > 0) {
    throw new Error(
      '[Semantic Aggregator Validator] resolved не может содержать unresolved conflict'
    );
  }
}


if (result.status === 'requires_recheck') {

  if (result.needs_recheck !== true) {
    throw new Error(
      '[Semantic Aggregator Validator] Для requires_recheck needs_recheck должен быть true'
    );
  }

  if (
    !ALLOWED_RECHECK_CODES.has(
      result.recheck_reason_code
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Некорректный recheck_reason_code: ${result.recheck_reason_code}`
    );
  }

  if (
    typeof result.recheck_note !== 'string' ||
    !result.recheck_note.trim()
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Для requires_recheck нужен recheck_note'
    );
  }

  if (primaryCount > 1) {
    throw new Error(
      `[Semantic Aggregator Validator] Для requires_recheck не может быть больше одного primary, получено ${primaryCount}`
    );
  }
}


// ============================================================
// 12. Применяем deterministic containment после всех raw validations
// ============================================================

const containmentApplied =
  resolvedContainmentEligible;

const suppressInvalidResolvedRoles =
  containmentApplied &&
  resolvedPrimaryCardinalityInvalid;

const effectiveCandidateDecisions =
  suppressInvalidResolvedRoles
    ? []
    : result.candidate_decisions;

const effectiveSupportingFactIds =
  suppressInvalidResolvedRoles
    ? []
    : result.supporting_fact_ids;

const effectiveConflictFactIds =
  suppressInvalidResolvedRoles
    ? []
    : result.conflict_fact_ids;

const effectiveStatus =
  containmentApplied
    ? 'requires_recheck'
    : result.status;

const effectiveNeedsRecheck =
  containmentApplied
    ? true
    : result.needs_recheck;

const effectiveRecheckReasonCode =
  containmentApplied
    ? 'insufficient_evidence'
    : result.recheck_reason_code;

const effectiveRecheckNote =
  containmentApplied
    ? containmentRule.reason
    : result.recheck_note;


// ============================================================
// 13. Возвращаем effective результат + полный raw provenance
// ============================================================

return {
  json: {
    analysis_run_id:
      source.analysis_run_id,

    field_catalog_version:
      source.field_catalog_version,

    field_index:
      source.field_index,

    field_key:
      source.field_key,

    aggregation_status:
      effectiveStatus,

    final_value_text:
      result.final_value_text ?? null,

    confidence:
      result.confidence,

    candidate_decisions:
      effectiveCandidateDecisions,

    supporting_fact_ids:
      effectiveSupportingFactIds,

    conflict_fact_ids:
      effectiveConflictFactIds,

    needs_recheck:
      effectiveNeedsRecheck,

    recheck_reason_code:
      effectiveRecheckReasonCode,

    recheck_note:
      effectiveRecheckNote,

    aggregation_input:
      source.aggregation_input,

    semantic_aggregator_meta: {
      response_id:
        aiResponse.id ?? null,

      model:
        aiResponse.model ?? null,

      finish_reason:
        choice.finish_reason,

      usage:
        aiResponse.usage ?? null,

      reported_result:
        result,

      reported_status:
        result.status,

      effective_status:
        effectiveStatus,

      containment_applied:
        containmentApplied,

      primary_count:
        primaryCount,

      raw_validation_issue:
        resolvedPrimaryCardinalityInvalid
          ? 'resolved_primary_count_must_equal_1'
          : null,

      containment_policy:
        containmentApplied
          ? (
              resolvedPrimaryCardinalityInvalid
                ? 'application_documents_round1_requires_recheck_v2'
                : containmentRule.policy
            )
          : null,

      containment_reason:
        containmentApplied
          ? containmentRule.reason
          : null,

      applicability_proof_kind:
        applicabilityAssessment.proof_kind,

      applicability_assessment:
        applicabilityAssessment,
    },

    aggregation_validated: true,
  },
};

