  !input.final_value_text.trim()
) {
  throw new Error(
    '[Сформировать FINAL после Round 1] Нет final_value_text'
  );
}

if (
  typeof input.confidence !== 'number' ||
  input.confidence < 0 ||
  input.confidence > 1
) {
  throw new Error(
    '[Сформировать FINAL после Round 1] Некорректный confidence'
  );
}


// ============================================================
// 2. Собираем evidence использованных кандидатов
// ============================================================

const candidates =
  Array.isArray(input.aggregation_input?.candidates)
    ? input.aggregation_input.candidates
    : [];

const decisions =
  Array.isArray(input.candidate_decisions)
    ? input.candidate_decisions
    : [];

const candidateByFactId = new Map(
  candidates
    .filter(candidate => candidate.fact_id)
    .map(candidate => [
      candidate.fact_id,
      candidate,
    ])
);


// В resolved-результат включаем evidence кандидатов,
// которые реально поддерживают итог.
//
// conflict и not_applicable в основной evidence не включаем.
const acceptedRoles = new Set([
  'primary',
  'duplicate',
  'supporting',
  'complement',
]);

const evidence = [];

for (const decision of decisions) {

  if (!acceptedRoles.has(decision.role)) {
    continue;
  }

  const candidate =
    candidateByFactId.get(decision.fact_id);

  if (!candidate) {
    throw new Error(
      `[Сформировать FINAL после Round 1] Не найден candidate для fact_id=${decision.fact_id}`
    );
  }

  const candidateEvidence =
    Array.isArray(candidate.evidence)
      ? candidate.evidence
      : [];

  for (const item of candidateEvidence) {
    evidence.push({
      ...item,

      candidate_ref:
        `fact:${decision.fact_id}`,

      candidate_role:
        decision.role,

      candidate_origin:
        'initial_analysis',

      candidate_value_text:
        candidate.value_text ?? null,
    });
  }
}


// ============================================================
// 3. Отдельно сохраняем conflict evidence для audit
// ============================================================

const conflictEvidence = [];

for (const decision of decisions) {

  if (decision.role !== 'conflict') {
    continue;
  }

  const candidate =
    candidateByFactId.get(decision.fact_id);

  if (!candidate) {
    continue;
  }

  for (const item of candidate.evidence ?? []) {
    conflictEvidence.push({
      ...item,

      candidate_ref:
        `fact:${decision.fact_id}`,

      candidate_role:
        'conflict',

      candidate_origin:
        'initial_analysis',

      candidate_value_text:
        candidate.value_text ?? null,
    });
  }
}


// ============================================================
// 4. Формируем FINAL перед общим нормализатором
// ============================================================

return {
  json: {
    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
      input.field_catalog_version,

    field_index:
      input.field_index,

    field_key:
      input.field_key,

    aggregation_status:
      'resolved',

    final_value_text:
      input.final_value_text,

    confidence:
      input.confidence,

    needs_recheck:
      false,

    aggregation_validated:
      true,

    requires_human_review:
      false,

    resolution_method:
      'semantic_aggregator_round_1',

    evidence,

    review_reason_code:
      null,

    review_note:
      null,

    aggregation_round:
      1,

    candidate_decisions:
      decisions,

    supporting_candidate_refs:
  Array.isArray(input.supporting_fact_ids)
    ? input.supporting_fact_ids.map(
        factId => `fact:${factId}`
      )
    : [],

conflict_candidate_refs:
  Array.isArray(input.conflict_fact_ids)
    ? input.conflict_fact_ids.map(
        factId => `fact:${factId}`
      )
    : [],

    conflict_evidence:
      conflictEvidence,

    semantic_aggregator_meta:
      input.semantic_aggregator_meta ?? null,
  },
};

