  );
}

if (
  !Array.isArray(input.evidence) ||
  input.evidence.length === 0
) {
  throw new Error(
    '[Сформировать FINAL из TenderMeta] Нет evidence'
  );
}


// ============================================================
// 2. Формируем FINAL перед общим нормализатором
// ============================================================

return {
  json: {
    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
