      null,

    aggregation_round:
      null,

    original_field:
      input.original_field ?? null,

    metadata_resolution: {
      metadata_resolved:
        true,

      resolution_method:
        input.resolution_method ?? 'deterministic_metadata',
    },
  },
};

const input = $json;


// ============================================================
// 1. Базовые проверки
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[Нормализовать FINAL поле] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Нормализовать FINAL поле] Нет field_key'
  );
}

if (input.aggregation_validated !== true) {
  throw new Error(
    '[Нормализовать FINAL поле] aggregation_validated должен быть true'
  );
}

if (input.needs_recheck !== false) {
  throw new Error(
    '[Нормализовать FINAL поле] FINAL поле не может иметь needs_recheck=true'
  );
}


// ============================================================
// 2. Допустимые FINAL-статусы
// ============================================================

const status =
  input.aggregation_status;

const ALLOWED_STATUSES =
  new Set([
    'resolved',
    'not_found',
    'requires_review',
  ]);

if (!ALLOWED_STATUSES.has(status)) {
  throw new Error(
    `[Нормализовать FINAL поле] Недопустимый aggregation_status=${status}`
  );
}


// ============================================================
// 3. resolution_method обязателен
// ============================================================

if (
  typeof input.resolution_method !== 'string' ||
  !input.resolution_method.trim()
) {
  throw new Error(
    '[Нормализовать FINAL поле] Нет resolution_method'
  );
}


// ============================================================
// 4. Evidence
// ============================================================

const evidence =
  Array.isArray(input.evidence)
    ? input.evidence
    : [];


// ============================================================
// 5. Проверяем RESOLVED
// ============================================================

if (status === 'resolved') {

  if (
    typeof input.final_value_text !== 'string' ||
    !input.final_value_text.trim()
  ) {
    throw new Error(
      '[Нормализовать FINAL поле] Для resolved нужен final_value_text'
    );
  }

  if (
    typeof input.confidence !== 'number' ||
    !Number.isFinite(input.confidence) ||
    input.confidence < 0 ||
    input.confidence > 1
  ) {
    throw new Error(
      `[Нормализовать FINAL поле] Некорректный confidence=${input.confidence}`
    );
  }
}


// ============================================================
// 6. Проверяем NOT_FOUND
// ============================================================

if (status === 'not_found') {

  if (input.final_value_text !== null) {
    throw new Error(
      '[Нормализовать FINAL поле] Для not_found final_value_text должен быть null'
    );
  }

  if (input.confidence !== null) {
    throw new Error(
      '[Нормализовать FINAL поле] Для not_found confidence должен быть null'
    );
  }

  if (
    typeof input.not_found_reason_code !== 'string' ||
    !input.not_found_reason_code
  ) {
    throw new Error(
      '[Нормализовать FINAL поле] Для not_found нужен not_found_reason_code'
    );
  }

  if (
    typeof input.not_found_note !== 'string' ||
    !input.not_found_note.trim()
  ) {
    throw new Error(
      '[Нормализовать FINAL поле] Для not_found нужен not_found_note'
    );
  }
}


// ============================================================
// 7. Проверяем REQUIRES_REVIEW
// ============================================================

